('11000003-71a0-4d01-9014-000000000001'::uuid,'0fb8ccaf-16a8-4d89-b683-3e2dd22ae5f4'::uuid,'Quelle structure contrôle la quantité de lumière entrant dans l’œil ?','L’iris ajuste la taille de la pupille et contrôle ainsi la quantité de lumière qui entre.','[{"text":"L’iris","correct":true},{"text":"La rétine","correct":false},{"text":"Le nerf optique","correct":false},{"text":"La sclère","correct":false}]'::jsonb,1,'NIH/NEI — How the Eyes Work',901,'source_validated',true,'mcq','[]'::jsonb,null,'{"source_url":"https://www.nei.nih.gov/eye-health-information/healthy-vision/how-eyes-work","source_validation":"institutional_validated"}'::jsonb),
('11000003-71a0-4d01-9014-000000000002'::uuid,'0fb8ccaf-16a8-4d89-b683-3e2dd22ae5f4'::uuid,'Quelle structure aide principalement à focaliser la lumière sur la rétine avec la cornée ?','Le cristallin travaille avec la cornée pour focaliser correctement la lumière sur la rétine.','[{"text":"Le cristallin","correct":true},{"text":"Le nerf auditif","correct":false},{"text":"Le tympan","correct":false},{"text":"La cochlée","correct":false}]'::jsonb,2,'NIH/NEI — How the Eyes Work',902,'source_validated',true,'mcq','[]'::jsonb,null,'{"source_validation":"institutional_validated"}'::jsonb),
('11000003-71a0-4d01-9014-000000000003'::uuid,'0fb8ccaf-16a8-4d89-b683-3e2dd22ae5f4'::uuid,'Par quelle structure les signaux visuels quittent-ils la rétine vers le cerveau ?','Les signaux électriques issus de la rétine gagnent le cerveau par le nerf optique.','[{"text":"Le nerf optique","correct":true},{"text":"Le nerf auditif","correct":false},{"text":"La trompe d’Eustache","correct":false},{"text":"Le diaphragme","correct":false}]'::jsonb,2,'NIH/NEI — How the Eyes Work',903,'source_validated',true,'mcq','[]'::jsonb,null,'{"source_validation":"institutional_validated"}'::jsonb),
('11000003-71a0-4d01-9014-000000000004'::uuid,'0fb8ccaf-16a8-4d89-b683-3e2dd22ae5f4'::uuid,'Que fait le tympan lorsqu’une onde sonore l’atteint ?','Le tympan vibre et transmet ces vibrations aux osselets de l’oreille moyenne.','[{"text":"Il vibre","correct":true},{"text":"Il transforme directement le son en image","correct":false},{"text":"Il ferme la pupille","correct":false},{"text":"Il produit la mélatonine","correct":false}]'::jsonb,2,'NIH/NIDCD — How Do We Hear?',904,'source_validated',true,'mcq','[]'::jsonb,null,'{"source_url":"https://www.nidcd.nih.gov/health/how-do-we-hear","source_validation":"institutional_validated"}'::jsonb),
('11000003-71a0-4d01-9014-000000000005'::uuid,'0fb8ccaf-16a8-4d89-b683-3e2dd22ae5f4'::uuid,'Quel est le rôle des osselets de l’oreille moyenne ?','Les osselets transmettent et amplifient les vibrations du tympan vers la cochlée.','[{"text":"Transmettre et amplifier les vibrations sonores","correct":true},{"text":"Transformer la lumière en signaux électriques","correct":false},{"text":"Réguler la glycémie","correct":false},{"text":"Former le clou plaquettaire","correct":false}]'::jsonb,2,'NIH/NIDCD — How Do We Hear?',905,'source_validated',true,'mcq','[]'::jsonb,null,'{"source_validation":"institutional_validated"}'::jsonb),
('11000003-71a0-4d01-9014-000000000006'::uuid,'0fb8ccaf-16a8-4d89-b683-3e2dd22ae5f4'::uuid,'Quelle structure de l’oreille interne est essentielle à l’audition ?','La cochlée transforme les vibrations mécaniques en signaux nerveux destinés au cerveau.','[{"text":"La cochlée","correct":true},{"text":"La cornée","correct":false},{"text":"La pupille","correct":false},{"text":"La rétine","correct":false}]'::jsonb,3,'NIH/NIDCD — How Do We Hear?',906,'source_validated',true,'mcq','[]'::jsonb,null,'{"source_validation":"institutional_validated"}'::jsonb),
('11000003-71a0-4d01-9014-000000000007'::uuid,'0fb8ccaf-16a8-4d89-b683-3e2dd22ae5f4'::uuid,'Quels systèmes contribuent ensemble au maintien de l’équilibre ?','L’équilibre utilise des informations provenant notamment du système vestibulaire, de la vision et des récepteurs musculaires et tactiles.','[{"text":"Vestibulaire, vision et proprioception","correct":true},{"text":"Digestion, coagulation et bile","correct":false},{"text":"ABO, mélatonine et insuline","correct":false},{"text":"Foie, peau et pancréas uniquement","correct":false}]'::jsonb,3,'NIH/NIDCD — Balance Disorders',907,'source_validated',true,'mcq','[]'::jsonb,null,'{"source_url":"https://www.nidcd.nih.gov/health/balance-disorders","source_validation":"institutional_validated"}'::jsonb),
('11000003-71a0-4d01-9014-000000000008'::uuid,'0fb8ccaf-16a8-4d89-b683-3e2dd22ae5f4'::uuid,'Cas d’application — Une lésion du nerf optique survient alors que la rétine transforme encore correctement la lumière. Quel problème est directement attendu ?','Le nerf optique transporte les signaux visuels de la rétine au cerveau ; sa lésion perturbe donc leur transmission.','[{"text":"Un défaut de transmission des signaux visuels vers le cerveau","correct":true},{"text":"Une perte de transmission des vibrations vers la cochlée","correct":false},{"text":"Une suppression de la coagulation","correct":false},{"text":"Une baisse automatique de la calcémie","correct":false}]'::jsonb,4,'NIH/NEI — How the Eyes Work',908,'source_validated',true,'clinical_case','[]'::jsonb,null,'{"source_validation":"institutional_validated"}'::jsonb),
('11000003-71a0-4d01-9014-000000000009'::uuid,'0fb8ccaf-16a8-4d89-b683-3e2dd22ae5f4'::uuid,'Quel raisonnement résume le mieux le fonctionnement sensoriel ?','Les organes sensoriels convertissent des stimuli en signaux nerveux qui sont transmis puis interprétés par le système nerveux central.','[{"text":"Transformer un stimulus en signal nerveux puis l’acheminer au cerveau","correct":true},{"text":"Transformer tous les stimuli directement en hormones","correct":false},{"text":"Utiliser uniquement le sang pour transmettre l’information sensorielle","correct":false},{"text":"Produire une réponse sans intervention du système nerveux","correct":false}]'::jsonb,5,'NIH/NEI + NIH/NIDCD — Sensory systems',909,'source_validated',true,'clinical_case','[]'::jsonb,null,'{"source_validation":"institutional_validated"}'::jsonb),
('11000002-71a0-4d01-9014-000000000001'::uuid,'6c33d990-2854-4813-a178-7f5e55958ddf'::uuid,'Quel organe est principalement lésé dans les maladies à prions humaines ?','Les maladies à prions entraînent principalement des lésions du cerveau et des troubles neurologiques.','[{"text":"Le cerveau","correct":true},{"text":"La vésicule biliaire","correct":false},{"text":"La peau uniquement","correct":false},{"text":"Le pancréas exocrine","correct":false}]'::jsonb,1,'CDC — About Prion Diseases',901,'source_validated',true,'mcq','[]'::jsonb,null,'{"source_url":"https://www.cdc.gov/prions/about/index.html","source_validation":"institutional_validated"}'::jsonb),
('11000002-71a0-4d01-9014-000000000002'::uuid,'6c33d990-2854-4813-a178-7f5e55958ddf'::uuid,'Quelle est la maladie à prions humaine la plus fréquente ?','La maladie de Creutzfeldt-Jakob est la maladie à prions la plus fréquente chez l’humain.','[{"text":"La maladie de Creutzfeldt-Jakob","correct":true},{"text":"La maladie de Crohn","correct":false},{"text":"La mucoviscidose","correct":false},{"text":"La polyarthrite rhumatoïde","correct":false}]'::jsonb,2,'CDC — About Prion Diseases',902,'source_validated',true,'mcq','[]'::jsonb,null,'{"source_validation":"institutional_validated"}'::jsonb),
('11000002-71a0-4d01-9014-000000000003'::uuid,'6c33d990-2854-4813-a178-7f5e55958ddf'::uuid,'Comment survient la majorité des cas de MCJ classique ?','La grande majorité des cas classiques sont sporadiques, sans cause identifiée.','[{"text":"De façon sporadique","correct":true},{"text":"Toujours par transmission alimentaire","correct":false},{"text":"Toujours par hérédité","correct":false},{"text":"Toujours après une chirurgie","correct":false}]'::jsonb,2,'CDC — Classic CJD',903,'source_validated',true,'mcq','[]'::jsonb,null,'{"source_url":"https://www.cdc.gov/creutzfeldt-jakob/about/","source_validation":"institutional_validated"}'::jsonb),
('11000002-71a0-4d01-9014-000000000004'::uuid,'6c33d990-2854-4813-a178-7f5e55958ddf'::uuid,'Existe-t-il des formes héréditaires de maladies à prions ?','Certaines maladies à prions peuvent être liées à des mutations génétiques héritées.','[{"text":"Oui","correct":true},{"text":"Non, jamais","correct":false},{"text":"Uniquement chez les animaux","correct":false},{"text":"Uniquement après vaccination","correct":false}]'::jsonb,2,'CDC — About Prion Diseases',904,'source_validated',true,'mcq','[]'::jsonb,null,'{"source_validation":"institutional_validated"}'::jsonb),
('11000002-71a0-4d01-9014-000000000005'::uuid,'6c33d990-2854-4813-a178-7f5e55958ddf'::uuid,'La forme variante de MCJ a été reliée à quelle maladie animale ?','La variante de MCJ a été reliée à l’encéphalopathie spongiforme bovine.','[{"text":"L’encéphalopathie spongiforme bovine","correct":true},{"text":"La rage canine","correct":false},{"text":"La grippe aviaire","correct":false},{"text":"La toxoplasmose","correct":false}]'::jsonb,2,'CDC — About Prion Diseases',905,'source_validated',true,'mcq','[]'::jsonb,null,'{"source_validation":"institutional_validated"}'::jsonb),
('11000002-71a0-4d01-9014-000000000006'::uuid,'6c33d990-2854-4813-a178-7f5e55958ddf'::uuid,'Quel traitement curatif est actuellement disponible contre les maladies à prions ?','Le CDC indique qu’il n’existe actuellement ni traitement curatif ni vaccin contre les maladies à prions.','[{"text":"Aucun traitement curatif disponible","correct":true},{"text":"Un antibiotique spécifique","correct":false},{"text":"Un vaccin curatif","correct":false},{"text":"Une insulinothérapie","correct":false}]'::jsonb,3,'CDC — About Prion Diseases',906,'source_validated',true,'mcq','[]'::jsonb,null,'{"source_validation":"institutional_validated"}'::jsonb),
('11000002-71a0-4d01-9014-000000000007'::uuid,'6c33d990-2854-4813-a178-7f5e55958ddf'::uuid,'Cas d’application — Un patient présente une dégradation neurologique rapidement progressive et une MCJ est évoquée. Quel type de processus est compatible ?','La MCJ provoque une neurodégénérescence rapidement progressive liée à l’accumulation de protéines prions mal repliées.','[{"text":"Une neurodégénérescence liée au mauvais repliement protéique","correct":true},{"text":"Une infection bactérienne classique","correct":false},{"text":"Une maladie exclusivement musculaire","correct":false},{"text":"Une maladie exclusivement endocrine","correct":false}]'::jsonb,3,'CDC — Classic CJD',907,'source_validated',true,'clinical_case','[]'::jsonb,null,'{"source_validation":"institutional_validated"}'::jsonb),
('11000002-71a0-4d01-9014-000000000008'::uuid,'6c33d990-2854-4813-a178-7f5e55958ddf'::uuid,'Pourquoi du matériel chirurgical contaminé a-t-il exceptionnellement été impliqué dans la transmission de MCJ ?','De rares cas acquis ont été liés à une exposition à des tissus ou équipements contaminés par des prions.','[{"text":"Parce que des prions peuvent être transmis par du matériel contaminé","correct":true},{"text":"Parce que les prions sont des bactéries aérosolisées","correct":false},{"text":"Parce que la MCJ se transmet toujours par l’air","correct":false},{"text":"Parce que tous les instruments contiennent naturellement des prions pathologiques","correct":false}]'::jsonb,4,'CDC — About Prion Diseases',908,'source_validated',true,'clinical_case','[]'::jsonb,null,'{"source_validation":"institutional_validated"}'::jsonb),
('11000002-71a0-4d01-9014-000000000009'::uuid,'6c33d990-2854-4813-a178-7f5e55958ddf'::uuid,'Quel raisonnement résume le mieux une maladie à prions ?','Une protéine mal repliée induit d’autres mauvais repliements, s’accumule et entraîne une neurodégénérescence progressive.','[{"text":"Propagation d’un mauvais repliement protéique avec atteinte cérébrale","correct":true},{"text":"Multiplication d’une bactérie dans le sang","correct":false},{"text":"Carence isolée en vitamine D","correct":false},{"text":"Réaction allergique cutanée","correct":false}]'::jsonb,5,'CDC — About Prion Diseases',909,'source_validated',true,'clinical_case','[]'::jsonb,null,'{"source_validation":"institutional_validated"}'::jsonb),
('11000001-71a0-4d01-9014-000000000001'::uuid,'b6d3b3eb-f25f-4e86-8a29-736de1d8a16d'::uuid,'Quel facteur environnemental influence le plus fortement les rythmes circadiens ?','L’alternance lumière-obscurité constitue le principal synchroniseur des rythmes circadiens.','[{"text":"La lumière et l’obscurité","correct":true},{"text":"Le groupe sanguin","correct":false},{"text":"La couleur des yeux","correct":false},{"text":"Le nombre de plaquettes","correct":false}]'::jsonb,1,'NIH/NIGMS — Circadian Rhythms',901,'source_validated',true,'mcq','[]'::jsonb,null,'{"source_url":"https://nigms.nih.gov/education/fact-sheets/Pages/circadian-rhythms","source_validation":"institutional_validated"}'::jsonb),
('11000001-71a0-4d01-9014-000000000002'::uuid,'b6d3b3eb-f25f-4e86-8a29-736de1d8a16d'::uuid,'Où se situe l’horloge maîtresse circadienne chez l’humain ?','L’horloge maîtresse se situe dans le noyau suprachiasmatique du cerveau.','[{"text":"Dans le noyau suprachiasmatique","correct":true},{"text":"Dans la vésicule biliaire","correct":false},{"text":"Dans la moelle osseuse","correct":false},{"text":"Dans le pancréas exocrine","correct":false}]'::jsonb,2,'NIH/NIGMS — Circadian Rhythms',902,'source_validated',true,'mcq','[]'::jsonb,null,'{"source_url":"https://nigms.nih.gov/education/fact-sheets/Pages/circadian-rhythms","source_validation":"institutional_validated"}'::jsonb),
('11000001-71a0-4d01-9014-000000000003'::uuid,'b6d3b3eb-f25f-4e86-8a29-736de1d8a16d'::uuid,'Quelle hormone est notamment modulée par l’horloge circadienne selon l’exposition lumineuse ?','Le noyau suprachiasmatique module notamment la production de mélatonine en fonction de la lumière reçue par les yeux.','[{"text":"La mélatonine","correct":true},{"text":"La fibrine","correct":false},{"text":"La bilirubine","correct":false},{"text":"L’hémoglobine","correct":false}]'::jsonb,2,'NIH/NIGMS — Circadian Rhythms',903,'source_validated',true,'mcq','[]'::jsonb,null,'{"source_url":"https://nigms.nih.gov/education/fact-sheets/Pages/circadian-rhythms","source_validation":"institutional_validated"}'::jsonb),
('11000001-71a0-4d01-9014-000000000004'::uuid,'b6d3b3eb-f25f-4e86-8a29-736de1d8a16d'::uuid,'Lequel est influencé par les rythmes circadiens ?','Les rythmes circadiens influencent notamment le sommeil, les hormones, l’appétit, la digestion et la température corporelle.','[{"text":"Le sommeil","correct":true},{"text":"Le groupe ABO uniquement","correct":false},{"text":"La séquence d’ADN uniquement","correct":false},{"text":"La structure osseuse uniquement","correct":false}]'::jsonb,2,'NIH/NIGMS — Circadian Rhythms',904,'source_validated',true,'mcq','[]'::jsonb,null,'{"source_validation":"institutional_validated"}'::jsonb),
('11000001-71a0-4d01-9014-000000000005'::uuid,'b6d3b3eb-f25f-4e86-8a29-736de1d8a16d'::uuid,'Les organes périphériques possèdent-ils aussi des rythmes circadiens ?','Presque tous les tissus et organes humains possèdent leurs propres rythmes circadiens, coordonnés par l’horloge maîtresse.','[{"text":"Oui","correct":true},{"text":"Non, seul le cerveau possède un rythme circadien","correct":false},{"text":"Non, seuls les muscles en possèdent","correct":false},{"text":"Non, seuls les reins en possèdent","correct":false}]'::jsonb,3,'NIH/NIGMS — Circadian Rhythms',905,'source_validated',true,'mcq','[]'::jsonb,null,'{"source_validation":"institutional_validated"}'::jsonb),
('11000001-71a0-4d01-9014-000000000006'::uuid,'b6d3b3eb-f25f-4e86-8a29-736de1d8a16d'::uuid,'Quel changement peut perturber fortement le rythme circadien ?','Le décalage horaire et le travail nocturne peuvent désynchroniser le cycle veille-sommeil.','[{"text":"Un changement important de fuseau horaire","correct":true},{"text":"Le changement de groupe sanguin","correct":false},{"text":"La croissance des cheveux","correct":false},{"text":"La couleur de la peau","correct":false}]'::jsonb,3,'NIH/NIGMS — Circadian Rhythms',906,'source_validated',true,'mcq','[]'::jsonb,null,'{"source_validation":"institutional_validated"}'::jsonb),
('11000001-71a0-4d01-9014-000000000007'::uuid,'b6d3b3eb-f25f-4e86-8a29-736de1d8a16d'::uuid,'Cas d’application — Après plusieurs nuits de travail, une personne présente somnolence et difficulté de concentration. Quel mécanisme peut y contribuer ?','Le travail de nuit peut désynchroniser les rythmes circadiens et perturber le cycle veille-sommeil.','[{"text":"Une désynchronisation circadienne","correct":true},{"text":"Une incompatibilité ABO","correct":false},{"text":"Une mutation obligatoire de l’ADN","correct":false},{"text":"Une thrombose certaine","correct":false}]'::jsonb,3,'NIH/NIGMS — Circadian Rhythms',907,'source_validated',true,'clinical_case','[]'::jsonb,null,'{"source_validation":"institutional_validated"}'::jsonb),
('11000001-71a0-4d01-9014-000000000008'::uuid,'b6d3b3eb-f25f-4e86-8a29-736de1d8a16d'::uuid,'Cas d’application — Une exposition lumineuse tardive modifie l’endormissement. Quelle voie de régulation est directement concernée ?','La lumière reçue par les yeux influence l’horloge maîtresse et la production de mélatonine.','[{"text":"Le couplage lumière–horloge circadienne–mélatonine","correct":true},{"text":"La coagulation plaquettaire","correct":false},{"text":"La sécrétion biliaire","correct":false},{"text":"La filtration glomérulaire","correct":false}]'::jsonb,4,'NIH/NIGMS — Circadian Rhythms',908,'source_validated',true,'clinical_case','[]'::jsonb,null,'{"source_validation":"institutional_validated"}'::jsonb),
('11000001-71a0-4d01-9014-000000000009'::uuid,'b6d3b3eb-f25f-4e86-8a29-736de1d8a16d'::uuid,'Quel raisonnement résume le mieux la chronobiologie circadienne ?','Une horloge biologique coordonne des rythmes d’environ 24 heures qui sont synchronisés par l’environnement et influencent de nombreuses fonctions corporelles.','[{"text":"Coordination interne de rythmes synchronisés avec l’environnement","correct":true},{"text":"Variation totalement aléatoire de toutes les fonctions","correct":false},{"text":"Contrôle exclusivement digestif","correct":false},{"text":"Absence d’influence de la lumière","correct":false}]'::jsonb,5,'NIH/NIGMS — Circadian Rhythms',909,'source_validated',true,'clinical_case','[]'::jsonb,null,'{"source_validation":"institutional_validated"}'::jsonb)
